'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "width": 306.0,
  "height": 142.0,
  "transform": [
    {
      "pivot": "Reminder Group",
      "value": "Pilot Stage Appointments",
      "groupby": [
        "Stage"
      ]
    },
    {
      "calculate": "datum[''Standard reminder''] + datum[''Enhanced reminder'']",
      "as": "v"
    },
    {
      "calculate": "-datum.v / 2",
      "as": "x0"
    },
    {
      "calculate": "datum.v / 2",
      "as": "x1"
    },
    {
      "calculate": "format(datum[''Standard reminder''], '','') + '' standard \u00b7 '' + format(datum[''Enhanced reminder''], '','') + '' enhanced''",
      "as": "split"
    }
  ],
  "autosize": {
    "type": "pad"
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "cornerRadius": 9
      },
      "encoding": {
        "y": {
          "field": "Stage",
          "type": "nominal",
          "sort": [
            "Assigned",
            "Attendance-eligible",
            "Attended"
          ],
          "scale": {
            "domain": [
              "Assigned",
              "Attendance-eligible",
              "Attended"
            ],
            "paddingInner": 0.18
          },
          "title": null,
          "axis": {
            "labelColor": "#101828",
            "labelFontSize": 11,
            "labelFontWeight": 600,
            "labelPadding": 10
          }
        },
        "x": {
          "type": "quantitative",
          "title": null,
          "axis": null,
          "scale": {
            "domain": [
              -720,
              720
            ]
          },
          "field": "x0"
        },
        "x2": {
          "field": "x1"
        },
        "color": {
          "field": "Stage",
          "type": "nominal",
          "scale": {
            "domain": [
              "Assigned",
              "Attendance-eligible",
              "Attended"
            ],
            "range": [
              "#104281",
              "#1C5CAB",
              "#3987E5"
            ]
          },
          "legend": null
        },
        "tooltip": [
          {
            "field": "Stage"
          },
          {
            "field": "v",
            "title": "Appointments",
            "format": ","
          },
          {
            "field": "split",
            "title": "Split"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "fontSize": 13,
        "fontWeight": 600,
        "color": "#FFFFFF",
        "dy": -6
      },
      "encoding": {
        "y": {
          "field": "Stage",
          "type": "nominal",
          "sort": [
            "Assigned",
            "Attendance-eligible",
            "Attended"
          ],
          "scale": {
            "domain": [
              "Assigned",
              "Attendance-eligible",
              "Attended"
            ],
            "paddingInner": 0.18
          },
          "title": null,
          "axis": {
            "labelColor": "#101828",
            "labelFontSize": 11,
            "labelFontWeight": 600,
            "labelPadding": 10
          }
        },
        "x": {
          "datum": 0,
          "type": "quantitative",
          "scale": {
            "domain": [
              -720,
              720
            ]
          }
        },
        "text": {
          "field": "v",
          "format": ","
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "fontSize": 9,
        "color": "#DCE8FB",
        "dy": 9
      },
      "encoding": {
        "y": {
          "field": "Stage",
          "type": "nominal",
          "sort": [
            "Assigned",
            "Attendance-eligible",
            "Attended"
          ],
          "scale": {
            "domain": [
              "Assigned",
              "Attendance-eligible",
              "Attended"
            ],
            "paddingInner": 0.18
          },
          "title": null,
          "axis": {
            "labelColor": "#101828",
            "labelFontSize": 11,
            "labelFontWeight": 600,
            "labelPadding": 10
          }
        },
        "x": {
          "datum": 0,
          "type": "quantitative",
          "scale": {
            "domain": [
              -720,
              720
            ]
          }
        },
        "text": {
          "field": "split"
        }
      }
    }
  ]
}'

'{
  "background": null,
  "font": "Segoe UI",
  "view": {
    "stroke": null
  },
  "padding": 2,
  "axis": {
    "labelFont": "Segoe UI",
    "labelFontSize": 10,
    "labelColor": "#667085",
    "titleFont": "Segoe UI",
    "titleFontSize": 10,
    "titleColor": "#667085",
    "titleFontWeight": "normal",
    "domain": false,
    "ticks": false,
    "gridColor": "#EEF0F4",
    "labelPadding": 6
  },
  "legend": {
    "labelFont": "Segoe UI",
    "labelFontSize": 10.5,
    "labelColor": "#344054",
    "symbolType": "circle",
    "symbolSize": 70,
    "title": null,
    "orient": "top",
    "direction": "horizontal",
    "columnPadding": 14
  },
  "text": {
    "font": "Segoe UI",
    "fontSize": 11,
    "color": "#344054"
  },
  "title": {
    "font": "Segoe UI"
  },
  "concat": {
    "spacing": 8
  }
}'
